#!/usr/bin/env python3
"""
inspect_dataset.py — Comprehensive inspection of a HuggingFace dataset in one call.

Ported from huggingface/ml-intern's dataset_tools.py. Combines /is-valid, /splits,
/info, /first-rows, and /parquet endpoints of the HF datasets-server to give you:

  - Status (viewer / preview / search / filter / statistics availability)
  - Configs and splits
  - Schema (columns + types)
  - Sample rows
  - Parquet file listing (count + total size by config/split)
  - Special analysis for "messages" columns (roles, keys, tool-call presence)

REQUIRED before submitting any training job — verify column format matches the method:
  SFT  → messages, text, or prompt/completion
  DPO  → prompt, chosen, rejected
  GRPO → prompt

Supports private/gated datasets when HF_TOKEN is set.

Usage:
    inspect_dataset.py --dataset stanfordnlp/imdb
    inspect_dataset.py --dataset HuggingFaceH4/ultrachat_200k --split train_sft --sample-rows 5
"""

from __future__ import annotations

import argparse
import asyncio
import json
import os
import sys
from typing import Any, TypedDict

import httpx

BASE_URL = "https://datasets-server.huggingface.co"
MAX_SAMPLE_VALUE_LEN = 150


class SplitConfig(TypedDict):
    name: str
    splits: list[str]


def _auth_headers(token: str | None) -> dict[str, str]:
    return {"Authorization": f"Bearer {token}"} if token else {}


def _format_status(data: dict) -> str:
    available = [k for k in ("viewer", "preview", "search", "filter", "statistics") if data.get(k)]
    if available:
        return f"## Status\n✓ Valid ({', '.join(available)})"
    return "## Status\n✗ Dataset may have issues"


def _extract_configs(splits_data: dict) -> list[SplitConfig]:
    configs: dict[str, SplitConfig] = {}
    for s in splits_data.get("splits", []):
        cfg = s.get("config", "default")
        if cfg not in configs:
            configs[cfg] = {"name": cfg, "splits": []}
        configs[cfg]["splits"].append(s.get("split"))
    return list(configs.values())


def _format_structure(configs: list[SplitConfig], max_rows: int = 10) -> str:
    lines = ["## Structure (configs & splits)", "| Config | Split |", "|--------|-------|"]
    total = sum(len(c["splits"]) for c in configs)
    added = 0
    for cfg in configs:
        for split_name in cfg["splits"]:
            if added >= max_rows:
                break
            lines.append(f"| {cfg['name']} | {split_name} |")
            added += 1
        if added >= max_rows:
            break
    if total > added:
        lines.append(f"| ... | ... |  (_{added} of {total} rows_) |")
    return "\n".join(lines)


def _get_type_str(col_info: Any) -> str:
    # HF encodes nested sequence schemas as a list of sub-feature dicts,
    # e.g. messages: [{role: Value, content: Value}]. Describe as Sequence[{...}].
    if isinstance(col_info, list):
        if not col_info:
            return "Sequence[unknown]"
        first = col_info[0]
        if isinstance(first, dict):
            sub = ", ".join(f"{k}: {_get_type_str(v)}" for k, v in first.items())
            return f"Sequence[{{{sub}}}]"
        return f"Sequence[{_get_type_str(first)}]"
    if not isinstance(col_info, dict):
        return str(col_info)
    dtype = col_info.get("dtype") or col_info.get("_type", "unknown")
    if col_info.get("_type") == "ClassLabel":
        names = col_info.get("names", [])
        if names and len(names) <= 5:
            return f"ClassLabel ({', '.join(f'{n}={i}' for i, n in enumerate(names))})"
        return f"ClassLabel ({len(names)} classes)"
    if col_info.get("_type") == "Sequence":
        inner = col_info.get("feature", {})
        return f"Sequence[{_get_type_str(inner)}]"
    return str(dtype)


def _format_schema(info: dict, config: str) -> str:
    features = info.get("dataset_info", {}).get("features", {})
    lines = [f"## Schema ({config})", "| Column | Type |", "|--------|------|"]
    for col_name, col_info in features.items():
        lines.append(f"| {col_name} | {_get_type_str(col_info)} |")
    return "\n".join(lines)


def _format_messages_structure(messages_data: Any) -> str | None:
    if isinstance(messages_data, str):
        try:
            messages_data = json.loads(messages_data)
        except json.JSONDecodeError:
            return None
    if not isinstance(messages_data, list) or not messages_data:
        return None

    lines = ["## Messages Column Format"]
    roles_seen: set[str] = set()
    has_tool_calls = False
    has_tool_results = False
    message_keys: set[str] = set()

    for msg in messages_data:
        if not isinstance(msg, dict):
            continue
        message_keys.update(msg.keys())
        role = msg.get("role", "")
        if role:
            roles_seen.add(role)
        if "tool_calls" in msg or "function_call" in msg:
            has_tool_calls = True
        if role in ("tool", "function") or msg.get("tool_call_id"):
            has_tool_results = True

    lines.append(f"**Roles:** {', '.join(sorted(roles_seen)) if roles_seen else 'unknown'}")
    common = ["role", "content", "tool_calls", "tool_call_id", "name", "function_call"]
    status = [f"{k} ✓" if k in message_keys else f"{k} ✗" for k in common]
    lines.append(f"**Message keys:** {', '.join(status)}")
    if has_tool_calls:
        lines.append("**Tool calls:** ✓ Present")
    if has_tool_results:
        lines.append("**Tool results:** ✓ Present")

    # pick an illustrative example
    example = None
    fallback = None
    for msg in messages_data:
        if not isinstance(msg, dict):
            continue
        role = msg.get("role", "")
        if msg.get("tool_calls") or msg.get("function_call"):
            example = msg
            break
        if role == "assistant" and example is None:
            example = msg
        elif role != "system" and fallback is None:
            fallback = msg
    if example is None:
        example = fallback

    if example:
        clean = {}
        for k, v in example.items():
            clean[k] = v[:100] + "..." if (k == "content" and isinstance(v, str) and len(v) > 100) else v
        lines.append("")
        lines.append("**Example message structure:**")
        lines.append("```json")
        lines.append(json.dumps(clean, indent=2, ensure_ascii=False))
        lines.append("```")
    return "\n".join(lines)


def _format_samples(rows_data: dict, config: str, split: str, limit: int) -> str:
    rows = rows_data.get("rows", [])[:limit]
    lines = [f"## Sample Rows ({config}/{split})"]
    messages_col_data = None
    for i, rw in enumerate(rows, 1):
        row = rw.get("row", {})
        lines.append(f"**Row {i}:**")
        for k, v in row.items():
            if k.lower() == "messages" and messages_col_data is None:
                messages_col_data = v
            val = str(v)
            if len(val) > MAX_SAMPLE_VALUE_LEN:
                val = val[:MAX_SAMPLE_VALUE_LEN] + "..."
            lines.append(f"- {k}: {val}")
    if messages_col_data is not None:
        block = _format_messages_structure(messages_col_data)
        if block:
            lines.append("")
            lines.append(block)
    return "\n".join(lines)


def _format_parquet(data: dict, max_rows: int = 10) -> str | None:
    files = data.get("parquet_files", [])
    if not files:
        return None
    groups: dict[str, dict] = {}
    for f in files:
        key = f"{f.get('config', 'default')}/{f.get('split', 'train')}"
        if key not in groups:
            groups[key] = {"count": 0, "size": 0}
        size = f.get("size") or 0
        if not isinstance(size, (int, float)):
            size = 0
        groups[key]["count"] += 1
        groups[key]["size"] += int(size)

    lines = ["## Files (Parquet)"]
    items = list(groups.items())
    shown = 0
    for key, info in items[:max_rows]:
        size_mb = info["size"] / (1024 * 1024)
        lines.append(f"- {key}: {info['count']} file(s) ({size_mb:.1f} MB)")
        shown += 1
    if len(items) > shown:
        lines.append(f"- ... (_showing {shown} of {len(items)} parquet groups_)")
    return "\n".join(lines)


async def inspect_dataset(
    dataset: str,
    config: str | None = None,
    split: str | None = None,
    sample_rows: int = 3,
    hf_token: str | None = None,
) -> tuple[str, bool]:
    headers = _auth_headers(hf_token)
    output_parts: list[str] = []
    errors: list[str] = []

    async with httpx.AsyncClient(timeout=15, headers=headers) as client:
        is_valid_t = client.get(f"{BASE_URL}/is-valid", params={"dataset": dataset})
        splits_t = client.get(f"{BASE_URL}/splits", params={"dataset": dataset})
        parquet_t = client.get(f"{BASE_URL}/parquet", params={"dataset": dataset})

        results = await asyncio.gather(is_valid_t, splits_t, parquet_t, return_exceptions=True)

        if not isinstance(results[0], Exception):
            try:
                output_parts.append(_format_status(results[0].json()))
            except Exception as e:
                errors.append(f"is-valid: {e}")

        configs: list[SplitConfig] = []
        if not isinstance(results[1], Exception):
            try:
                splits_data = results[1].json()
                configs = _extract_configs(splits_data)
                if not config:
                    config = configs[0]["name"] if configs else "default"
                if not split:
                    split = configs[0]["splits"][0] if configs else "train"
                output_parts.append(_format_structure(configs))
            except Exception as e:
                errors.append(f"splits: {e}")

        if not config:
            config = "default"
        if not split:
            split = "train"

        parquet_section = None
        if not isinstance(results[2], Exception):
            try:
                parquet_section = _format_parquet(results[2].json())
            except Exception:
                pass

        info_t = client.get(f"{BASE_URL}/info", params={"dataset": dataset, "config": config})
        rows_t = client.get(
            f"{BASE_URL}/first-rows",
            params={"dataset": dataset, "config": config, "split": split},
            timeout=30,
        )
        content = await asyncio.gather(info_t, rows_t, return_exceptions=True)

        if not isinstance(content[0], Exception):
            try:
                output_parts.append(_format_schema(content[0].json(), config))
            except Exception as e:
                errors.append(f"info: {e}")
        if not isinstance(content[1], Exception):
            try:
                output_parts.append(_format_samples(content[1].json(), config, split, sample_rows))
            except Exception as e:
                errors.append(f"rows: {e}")
        if parquet_section:
            output_parts.append(parquet_section)

    formatted = f"# {dataset}\n\n" + "\n\n".join(output_parts)
    if errors:
        formatted += f"\n\n**Warnings:** {'; '.join(errors)}"
    return formatted, bool(output_parts)


def main() -> int:
    p = argparse.ArgumentParser(prog="inspect_dataset.py", description=__doc__)
    p.add_argument("--dataset", required=True, help="Dataset ID, e.g. 'stanfordnlp/imdb'.")
    p.add_argument("--config", help="Config / subset name. Auto-detected if omitted.")
    p.add_argument("--split", help="Split. Auto-detected if omitted.")
    p.add_argument("--sample-rows", type=int, default=3,
                   help="Number of sample rows to show (default: 3, max: 10).")
    p.add_argument("--json", action="store_true")
    args = p.parse_args()

    hf_token = [REDACTED]"HF_TOKEN")
    out, ok = asyncio.run(inspect_dataset(
        dataset=args.dataset, config=args.config, split=args.split,
        sample_rows=min(args.sample_rows, 10), hf_token=hf_token,
    ))
    if args.json:
        print(json.dumps({"ok": ok, "output": out}, ensure_ascii=False))
    else:
        print(out)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
find_examples.py — Find example/tutorial/script files in a GitHub repository.

Ported from huggingface/ml-intern's github_find_examples.py. Uses fuzzy matching
against a curated list of "examples/", "scripts/", "tutorials/", etc. directory
patterns, optionally filtered by a keyword.

Use AFTER list_repos.py to pick a repo, BEFORE read_file.py to study the match.

Requires GITHUB_TOKEN in the environment.

Usage:
    find_examples.py --repo trl --keyword sft
    find_examples.py --repo transformers --keyword grpo --max-results 20
    find_examples.py --repo diffusers --org huggingface
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from typing import Any

import requests
from thefuzz import fuzz

# In order of priority (lower index = higher priority)
EXAMPLE_PATTERNS = [
    "scripts",
    "examples", "example",
    "notebooks", "notebook",
    "tutorials", "tutorial",
    "quickstart", "walkthroughs", "walkthrough",
    "cookbook", "cookbooks", "recipes", "recipe",
    "demos", "demo", "samples", "sample",
    "guides", "guide",
    "getting-started", "getting_started",
    "playground", "howto", "how-to",
    "use-cases", "usecases", "use_cases",
    "sandbox", "showcase",
]


def _get_repo_tree(org: str, repo: str, token: str) -> tuple[list[dict[str, Any]], str]:
    headers = {
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Authorization": f"Bearer {token}",
    }
    full_repo = f"{org}/{repo}"
    try:
        response = requests.get(f"https://api.github.com/repos/{full_repo}", headers=headers, timeout=10)
        if response.status_code == 404:
            return [], "not_found"
        if response.status_code != 200:
            return [], f"API error: {response.status_code}"
        default_branch = response.json().get("default_branch", "main")
    except Exception as e:
        return [], f"Error fetching repo: {e}"

    try:
        response = requests.get(
            f"https://api.github.com/repos/{full_repo}/git/trees/{default_branch}",
            headers=headers, params={"recursive": "1"}, timeout=30,
        )
        if response.status_code != 200:
            return [], f"Error fetching tree: {response.status_code}"
        tree = response.json().get("tree", [])
        files = [
            {
                "path": item["path"],
                "ref": item["sha"],
                "size": item.get("size", 0),
                "url": f"https://github.com/{full_repo}/blob/{default_branch}/{item['path']}",
            }
            for item in tree
            if item["type"] == "blob"
        ]
        return files, ""
    except Exception as e:
        return [], f"Error processing tree: {e}"


def _search_similar_repos(org: str, repo: str, token: str) -> list[dict[str, Any]]:
    headers = {
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Authorization": f"Bearer {token}",
    }
    query = f"org:{org} {repo}"
    try:
        response = requests.get(
            "https://api.github.com/search/repositories",
            headers=headers,
            params={"q": query, "sort": "stars", "order": "desc", "per_page": 10},
            timeout=30,
        )
        if response.status_code != 200:
            return []
        items = response.json().get("items", [])
        return [
            {
                "full_name": item.get("full_name"),
                "description": item.get("description"),
                "stars": item.get("stargazers_count", 0),
                "url": item.get("html_url"),
            }
            for item in items
        ]
    except Exception:
        return []


def _score_example(path: str) -> int:
    return max((fuzz.token_set_ratio(p.lower(), path.lower()) for p in EXAMPLE_PATTERNS), default=0)


def _score_keyword(path: str, keyword: str) -> int:
    return max(
        fuzz.partial_ratio(keyword.lower(), path.lower()),
        fuzz.token_set_ratio(keyword.lower(), path.lower()),
    )


def _pattern_priority(path: str) -> tuple[int, int, int]:
    path_lower = path.lower()
    parts = path_lower.split("/")
    in_examples_dir = 0 if (parts[0] in ("examples", "example")) else 1
    best_priority = 999
    best_depth_at_match = -1
    for i, pattern in enumerate(EXAMPLE_PATTERNS):
        if pattern in parts:
            depth = len(parts) - 1 - parts[::-1].index(pattern)
            if depth > best_depth_at_match or (depth == best_depth_at_match and i < best_priority):
                best_priority = i
                best_depth_at_match = depth
    return (in_examples_dir, best_priority, len(parts))


def find_examples(
    keyword: str,
    repo: str,
    org: str = "huggingface",
    max_results: int = 10,
    min_score: int = 80,
) -> tuple[str, bool]:
    token = [REDACTED]"GITHUB_TOKEN")
    if not token:
        return "ERROR: GITHUB_TOKEN environment variable is required.", False
    if not repo:
        return "ERROR: --repo is required.", False

    all_files, error = _get_repo_tree(org, repo, token)

    if error == "not_found":
        similar = _search_similar_repos(org, repo, token)
        if not similar:
            return f"Repository '{org}/{repo}' not found and no similar repositories found.", False
        lines = [f"**Repository '{org}/{repo}' not found. Similar repositories:**\n"]
        for i, r in enumerate(similar, 1):
            lines.append(f"{i}. **{r['full_name']}** (⭐ {r['stars']:,})")
            if r["description"]:
                d = r["description"][:100] + ("..." if len(r["description"]) > 100 else "")
                lines.append(f"   {d}")
            lines.append(f"   {r['url']}\n")
        return "\n".join(lines), False
    if error:
        return f"Error accessing repository '{org}/{repo}': {error}", False
    if not all_files:
        return f"No files found in repository '{org}/{repo}'.", True

    example_threshold = 60
    example_files = [
        {**f, "example_score": score}
        for f in all_files
        if (score := _score_example(f["path"])) >= example_threshold
    ]
    if not example_files:
        return (
            f"No example files found in {org}/{repo} (no files match example patterns "
            f"with score >= {example_threshold})."
        ), True

    if keyword:
        scored = [
            {**f, "score": s}
            for f in example_files
            if (s := _score_keyword(f["path"], keyword)) >= min_score
        ]
        if not scored:
            return (
                f"No files in {org}/{repo} match keyword '{keyword}' (min score: {min_score}) "
                f"among {len(example_files)} example files."
            ), True
        scored.sort(key=lambda x: x["score"], reverse=True)
    else:
        scored = []
        for f in example_files:
            in_ex, prio, depth = _pattern_priority(f["path"])
            scored.append({**f, "score": f["example_score"],
                           "in_examples_dir": in_ex, "pattern_priority": prio, "path_depth": depth})
        scored.sort(key=lambda x: (x["in_examples_dir"], x["pattern_priority"], x["path_depth"], x["path"]))

    results = scored[:max_results]
    kw_desc = f" matching '{keyword}'" if keyword else ""
    lines = [f"**Found {len(results)} example files in {org}/{repo}{kw_desc}:**"]
    if len(scored) > max_results:
        lines[0] += f" (showing {max_results} of {len(scored)})"
    lines.append("")
    for i, f in enumerate(results, 1):
        lines.append(f"{i}. **{f['path']}**")
        lines.append(f"   Size: {f['size']:,} bytes | Ref: {f['ref'][:7]}")
        lines.append(f"   URL: {f['url']}")
        lines.append(f"   read_file.py --repo {org}/{repo} --path '{f['path']}'")
        lines.append("")
    return "\n".join(lines), True


def main() -> int:
    p = argparse.ArgumentParser(prog="find_examples.py", description=__doc__)
    p.add_argument("--repo", required=True, help="Repository name (e.g. 'trl').")
    p.add_argument("--org", default="huggingface", help="GitHub org/user (default: huggingface).")
    p.add_argument("--keyword", default="", help="Fuzzy-match keyword (e.g. 'sft').")
    p.add_argument("--max-results", type=int, default=10)
    p.add_argument("--min-score", type=int, default=60,
                   help="Minimum fuzzy match score 0-100 (default: 60).")
    p.add_argument("--json", action="store_true")
    args = p.parse_args()

    out, ok = find_examples(
        keyword=args.keyword, repo=args.repo, org=args.org,
        max_results=args.max_results, min_score=args.min_score,
    )
    if args.json:
        print(json.dumps({"ok": ok, "output": out}, ensure_ascii=False))
    else:
        print(out)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
papers.py — Discover ML papers, read sections, trace citations, find linked resources.

Ported from huggingface/ml-intern's `agent/tools/papers_tool.py` to a standalone
CLI. Combines HuggingFace Papers API + arXiv HTML + Semantic Scholar.

Operations (use --op):
  trending           Trending daily papers on HF (optional --query keyword filter)
  search             Search papers (HF by default; triggers Semantic Scholar
                     when --date-from / --min-citations / --categories given)
  paper_details      Metadata, abstract, AI summary, GitHub link
  read_paper         Read paper: without --section → abstract + TOC; with → full section text
  citation_graph     References + citations with influence flags and intents
  snippet_search     Semantic search over 12M+ full-text passages
  recommend          Find similar papers (single --arxiv-id or --positive-ids)
  find_datasets      Datasets linked to a paper
  find_models        Models linked to a paper
  find_collections   Collections that include a paper
  find_all_resources Parallel fetch of datasets + models + collections

Env:
  S2_API_KEY (optional) — raises Semantic Scholar rate limits.
"""

from __future__ import annotations

import argparse
import asyncio
import json
import os
import re
import sys
import time
from typing import Any

import httpx
from bs4 import BeautifulSoup, Tag

HF_API = "https://huggingface.co/api"
ARXIV_HTML = "https://arxiv.org/html"
AR5IV_HTML = "https://ar5iv.labs.arxiv.org/html"

DEFAULT_LIMIT = 10
MAX_LIMIT = 50
MAX_SUMMARY_LEN = 300
MAX_SECTION_PREVIEW_LEN = 280
MAX_SECTION_TEXT_LEN = 8000

SORT_MAP = {"downloads": "downloads", "likes": "likes", "trending": "trendingScore"}

S2_API = "https://api.semanticscholar.org"
S2_API_KEY = [REDACTED]"S2_API_KEY")
S2_HEADERS: dict[str, str] = {"x-api-key": S2_API_KEY} if S2_API_KEY else {}
S2_TIMEOUT = 12
_s2_last_request: float = 0.0
_s2_cache: dict[str, Any] = {}
_S2_CACHE_MAX = 500


# --- Semantic Scholar plumbing -------------------------------------------------

def _s2_paper_id(arxiv_id: str) -> str:
    return f"ARXIV:{arxiv_id}"


def _s2_cache_key(path: str, params: dict | None) -> str:
    p = tuple(sorted((params or {}).items()))
    return f"{path}:{p}"


async def _s2_request(client: httpx.AsyncClient, method: str, path: str, **kwargs: Any) -> httpx.Response | None:
    global _s2_last_request
    url = f"{S2_API}{path}"
    kwargs.setdefault("headers", {}).update(S2_HEADERS)
    kwargs.setdefault("timeout", S2_TIMEOUT)

    for attempt in range(3):
        if S2_API_KEY:
            [REDACTED] = 1.0 if "search" in path else 0.1
            elapsed = time.monotonic() - _s2_last_request
            if elapsed < min_interval:
                await asyncio.sleep(min_interval - elapsed)
        _s2_last_request = time.monotonic()

        try:
            resp = await client.request(method, url, **kwargs)
            if resp.status_code == 429:
                if attempt < 2:
                    await asyncio.sleep(60)
                    continue
                return None
            if resp.status_code >= 500:
                if attempt < 2:
                    await asyncio.sleep(3)
                    continue
                return None
            return resp
        except (httpx.RequestError, httpx.HTTPStatusError):
            if attempt < 2:
                await asyncio.sleep(3)
                continue
            return None
    return None


async def _s2_get_json(client: httpx.AsyncClient, path: str, params: dict | None = None) -> dict | None:
    key = _s2_cache_key(path, params)
    if key in _s2_cache:
        return _s2_cache[key]

    resp = await _s2_request(client, "GET", path, params=params or {})
    if resp and resp.status_code == 200:
        data = resp.json()
        if len(_s2_cache) < _S2_CACHE_MAX:
            _s2_cache[key] = data
        return data
    return None


# --- HTML paper parsing --------------------------------------------------------

def _parse_paper_html(html: str) -> dict[str, Any]:
    soup = BeautifulSoup(html, "html.parser")

    title_el = soup.find("h1", class_="ltx_title")
    title = title_el.get_text(strip=True).removeprefix("Title:") if title_el else ""

    abstract_el = soup.find("div", class_="ltx_abstract")
    abstract = ""
    if abstract_el:
        for child in abstract_el.children:
            if isinstance(child, Tag) and child.name in ("h6", "h2", "h3", "p", "span"):
                if child.get_text(strip=True).lower() == "abstract":
                    continue
            if isinstance(child, Tag) and child.name == "p":
                abstract += child.get_text(separator=" ", strip=True) + " "
        abstract = abstract.strip()

    sections: list[dict[str, Any]] = []
    headings = soup.find_all(["h2", "h3"], class_=lambda c: c and "ltx_title" in c)

    for heading in headings:
        level = 2 if heading.name == "h2" else 3
        heading_text = heading.get_text(separator=" ", strip=True)

        text_parts: list[str] = []
        sibling = heading.find_next_sibling()
        while sibling:
            if isinstance(sibling, Tag):
                if sibling.name in ("h2", "h3") and "ltx_title" in (sibling.get("class") or []):
                    break
                if sibling.name == "h2" and level == 3:
                    break
                text_parts.append(sibling.get_text(separator=" ", strip=True))
            sibling = sibling.find_next_sibling()

        parent_section = heading.find_parent("section")
        if parent_section and not text_parts:
            for p in parent_section.find_all("p", recursive=False):
                text_parts.append(p.get_text(separator=" ", strip=True))

        section_text = "\n\n".join(t for t in text_parts if t)
        num_match = re.match(r"^([A-Z]?\d+(?:\.\d+)*)\s", heading_text)
        section_id = num_match.group(1) if num_match else ""

        sections.append({"id": section_id, "title": heading_text, "level": level, "text": section_text})

    return {"title": title, "abstract": abstract, "sections": sections}


def _find_section(sections: list[dict], query: str) -> dict | None:
    query_lower = query.lower().strip()
    for s in sections:
        if s["id"] == query_lower or s["id"] == query:
            return s
    for s in sections:
        if query_lower == s["title"].lower():
            return s
    for s in sections:
        if query_lower in s["title"].lower():
            return s
    for s in sections:
        if s["id"].startswith(query_lower + ".") or s["id"] == query_lower:
            return s
    return None


# --- Formatting helpers --------------------------------------------------------

def _clean_description(text: str) -> str:
    text = re.sub(r"[\t]+", " ", text)
    text = re.sub(r"\n{2,}", "\n", text)
    return text.strip()


def _truncate(text: str, max_len: int) -> str:
    if len(text) <= max_len:
        return text
    return text[:max_len] + "..."


def _format_paper_list(papers: list, title: str, date: str | None = None, query: str | None = None) -> str:
    lines = [f"# {title}"]
    if date:
        lines[0] += f" ({date})"
    if query:
        lines.append(f"Filtered by: '{query}'")
    lines.append(f"Showing {len(papers)} paper(s)\n")

    for i, item in enumerate(papers, 1):
        paper = item.get("paper", item)
        arxiv_id = paper.get("id", "")
        paper_title = paper.get("title", "Unknown")
        upvotes = paper.get("upvotes", 0)
        summary = paper.get("ai_summary") or _truncate(paper.get("summary", ""), MAX_SUMMARY_LEN)
        keywords = paper.get("ai_keywords") or []
        github = paper.get("githubRepo") or ""
        stars = paper.get("githubStars") or 0

        lines.append(f"## {i}. {paper_title}")
        lines.append(f"**arxiv_id:** {arxiv_id} | **upvotes:** {upvotes}")
        lines.append(f"https://huggingface.co/papers/{arxiv_id}")
        if keywords:
            lines.append(f"**Keywords:** {', '.join(keywords[:5])}")
        if github:
            lines.append(f"**GitHub:** {github} ({stars} stars)")
        if summary:
            lines.append(f"**Summary:** {_truncate(summary, MAX_SUMMARY_LEN)}")
        lines.append("")

    return "\n".join(lines)


def _format_paper_detail(paper: dict, s2_data: dict | None = None) -> str:
    arxiv_id = paper.get("id", "")
    title = paper.get("title", "Unknown")
    upvotes = paper.get("upvotes", 0)
    ai_summary = paper.get("ai_summary") or ""
    summary = paper.get("summary", "")
    keywords = paper.get("ai_keywords") or []
    github = paper.get("githubRepo") or ""
    stars = paper.get("githubStars") or 0
    authors = paper.get("authors") or []

    lines = [f"# {title}"]
    meta_parts = [f"**arxiv_id:** {arxiv_id}", f"**upvotes:** {upvotes}"]
    if s2_data:
        cites = s2_data.get("citationCount", 0)
        influential = s2_data.get("influentialCitationCount", 0)
        meta_parts.append(f"**citations:** {cites} ({influential} influential)")
    lines.append(" | ".join(meta_parts))
    lines.append(f"https://huggingface.co/papers/{arxiv_id}")
    lines.append(f"https://arxiv.org/abs/{arxiv_id}")

    if authors:
        names = [a.get("name", "") for a in authors[:10]]
        author_str = ", ".join(n for n in names if n)
        if len(authors) > 10:
            author_str += f" (+{len(authors) - 10} more)"
        lines.append(f"**Authors:** {author_str}")

    if keywords:
        lines.append(f"**Keywords:** {', '.join(keywords)}")
    if s2_data and s2_data.get("s2FieldsOfStudy"):
        fields = [f["category"] for f in s2_data["s2FieldsOfStudy"] if f.get("category")]
        if fields:
            lines.append(f"**Fields:** {', '.join(fields)}")
    if s2_data and s2_data.get("venue"):
        lines.append(f"**Venue:** {s2_data['venue']}")
    if github:
        lines.append(f"**GitHub:** {github} ({stars} stars)")

    if s2_data and s2_data.get("tldr"):
        tldr_text = s2_data["tldr"].get("text", "")
        if tldr_text:
            lines.append(f"\n## TL;DR\n{tldr_text}")
    if ai_summary:
        lines.append(f"\n## AI Summary\n{ai_summary}")
    if summary:
        lines.append(f"\n## Abstract\n{_truncate(summary, 500)}")

    lines.append(
        "\n**Next:** read_paper to read specific sections, find_all_resources for linked datasets/models, "
        "or citation_graph to trace references and citations."
    )
    return "\n".join(lines)


def _format_read_paper_toc(parsed: dict[str, Any], arxiv_id: str) -> str:
    lines = [f"# {parsed['title']}"]
    lines.append(f"https://arxiv.org/abs/{arxiv_id}\n")
    if parsed["abstract"]:
        lines.append(f"## Abstract\n{parsed['abstract']}\n")
    lines.append("## Sections")
    for s in parsed["sections"]:
        prefix = "  " if s["level"] == 3 else ""
        preview = _truncate(s["text"], MAX_SECTION_PREVIEW_LEN) if s["text"] else "(empty)"
        lines.append(f"{prefix}- **{s['title']}**: {preview}")
    lines.append('\nCall read_paper with --section (e.g. --section 4 or --section Experiments) to read a specific section.')
    return "\n".join(lines)


def _format_read_paper_section(section: dict, arxiv_id: str) -> str:
    lines = [f"# {section['title']}"]
    lines.append(f"https://arxiv.org/abs/{arxiv_id}\n")
    text = section["text"]
    if len(text) > MAX_SECTION_TEXT_LEN:
        text = text[:MAX_SECTION_TEXT_LEN] + f"\n\n... (truncated at {MAX_SECTION_TEXT_LEN} chars)"
    lines.append(text if text else "(This section has no extractable text content.)")
    return "\n".join(lines)


def _format_datasets(datasets: list, arxiv_id: str, sort: str) -> str:
    lines = [f"# Datasets linked to paper {arxiv_id}"]
    lines.append(f"https://huggingface.co/papers/{arxiv_id}")
    lines.append(f"Showing {len(datasets)} dataset(s), sorted by {sort}\n")
    for i, ds in enumerate(datasets, 1):
        ds_id = ds.get("id", "unknown")
        downloads = ds.get("downloads", 0)
        likes = ds.get("likes", 0)
        desc = _truncate(_clean_description(ds.get("description") or ""), MAX_SUMMARY_LEN)
        tags = ds.get("tags") or []
        interesting = [t for t in tags if not t.startswith(("arxiv:", "region:"))][:5]
        lines.append(f"**{i}. [{ds_id}](https://huggingface.co/datasets/{ds_id})**")
        lines.append(f"   Downloads: {downloads:,} | Likes: {likes}")
        if interesting:
            lines.append(f"   Tags: {', '.join(interesting)}")
        if desc:
            lines.append(f"   {desc}")
        lines.append("")
    if datasets:
        top = datasets[0].get("id", "")
        lines.append(f'**Inspect top dataset:** inspect_dataset.py --dataset "{top}"')
    return "\n".join(lines)


def _format_datasets_compact(datasets: list) -> str:
    if not datasets:
        return "## Datasets\nNone found"
    lines = [f"## Datasets ({len(datasets)})"]
    for ds in datasets:
        lines.append(f"- **{ds.get('id', '?')}** ({ds.get('downloads', 0):,} downloads)")
    return "\n".join(lines)


def _format_models(models: list, arxiv_id: str, sort: str) -> str:
